"use strict";(globalThis.webpackChunklearngenomics_dev||=[]).push([[9479],{1869(e,n,t){t.r(n),t.d(n,{assets:()=>g,contentTitle:()=>d,default:()=>u,frontMatter:()=>l,metadata:()=>i,toc:()=>p});var s=t.cw((e,n)=>{const s=t.p+"assets/images/2.6-ras-mapk-dark-956ec37333cc8fff7f5c3c1979df5a72.svg";t.d(n,["A",0,s])}),a=t.cw((e,n)=>{const s=t.p+"assets/images/2.7-two-brakes-dark-a5e3cdae431309fa0523ae3cbc3d31c9.svg";t.d(n,["A",0,s])}),o=t.cw((e,n)=>{const s=t.p+"assets/images/2.6-ras-mapk-538f6ea43755c68b58a92a8ac4cc62a6.svg";t.d(n,["A",0,s])}),r=t.cw((e,n)=>{const s=t.p+"assets/images/2.7-two-brakes-de218e341e63a76b8dc4ad1f3715c51a.svg";t.d(n,["A",0,s])});const i=JSON.parse('{"id":"cancer-biology/signaling-pathways","title":"Signaling Pathways","description":"A cell in the body doesn\'t decide to divide on its own. It waits for signals from","source":"@site/docs/02-cancer-biology/04-signaling-pathways.md","sourceDirName":"02-cancer-biology","slug":"/cancer-biology/signaling-pathways","permalink":"/docs/cancer-biology/signaling-pathways","draft":false,"unlisted":false,"editUrl":"https://github.com/stjude/learngenomics.dev/tree/main/docs/02-cancer-biology/04-signaling-pathways.md","tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"title":"Signaling Pathways"},"sidebar":"tutorialSidebar","previous":{"title":"Oncogenes and Tumor Suppressors","permalink":"/docs/cancer-biology/oncogenes-and-tumor-suppressors"},"next":{"title":"How Tumors Evolve","permalink":"/docs/cancer-biology/how-tumors-evolve"}}');var h=t(4848),c=t(8453);const l={title:"Signaling Pathways"},d=void 0,g={},p=[{value:"Passing the Signal",id:"passing-the-signal",level:2},{value:"Locking the Relay On",id:"locking-the-relay-on",level:2},{value:"The RB Brake",id:"the-rb-brake",level:2},{value:"The p53 Brake",id:"the-p53-brake",level:2},{value:"Up Next",id:"up-next",level:2}];function m(e){const n={a:"a",em:"em",figcaption:"figcaption",figure:"figure",h2:"h2",img:"img",p:"p",span:"span",strong:"strong",...(0,c.R)(),...e.components};return(0,h.jsxs)(h.Fragment,{children:[(0,h.jsxs)(n.p,{children:["A cell in the body doesn't decide to divide on its own. It waits for signals from\noutside, such as ",(0,h.jsx)(n.strong,{children:"growth factors"}),", small proteins released by other cells. The signal\narrives at the cell's surface, but the genes that carry out division sit in the nucleus,\nso a chain of proteins has to carry the message inward. Each protein in the chain\nswitches on the next, like runners passing a baton. A chain like this is called a\n",(0,h.jsx)(n.strong,{children:"signaling pathway"}),"."]}),"\n",(0,h.jsxs)(n.p,{children:["More than 600 genes are now known to drive cancer when they're mutated\n(",(0,h.jsx)(n.a,{href:"https://www.intogen.org/search",children:"IntOGen"}),"), but many of their proteins work in the same\nfew pathways. In a study of more than 9,000 tumors from 33 kinds of cancer, 89% had at\nleast one driver change in just ten well-known pathways (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2018.03.035",children:"Sanchez-Vega et al.,\n2018"}),"). This page follows one relay that is\nswitched on in a large share of cancers, then two brakes, RB and p53, that a tumor has\nto get past."]}),"\n",(0,h.jsx)(n.h2,{id:"passing-the-signal",children:"Passing the Signal"}),"\n",(0,h.jsxs)(n.p,{children:["The best-studied relay is the RAS\u2013MAPK pathway, which passes growth signals from the\ncell surface to the nucleus. It starts when a growth factor binds a ",(0,h.jsx)(n.strong,{children:"receptor"}),", a\nprotein that spans the cell membrane with one end outside the cell and the other inside.\nOne example is EGFR, the receptor for epidermal growth factor. EGFR is a kinase, an\nenzyme that adds phosphate groups to proteins, and ",(0,h.jsx)(n.a,{href:"/docs/biological-foundations/protein-folding-and-modification#kinases-as-switches",children:"Kinases as\nSwitches"}),"\nshows how a phosphate can switch a protein on or off. When the growth factor binds, the\nreceptor switches on and draws in helper proteins that switch on RAS."]}),"\n",(0,h.jsxs)(n.p,{children:["RAS works like a light switch. It holds a small molecule called GDP when it is off and\nswaps it for a similar molecule, GTP, to switch on. RAS can turn GTP back into GDP and\nswitch itself off, but only slowly. Proteins called ",(0,h.jsx)(n.strong,{children:"GAPs"})," speed this up, so a pulse\nof signal fades quickly once the growth factor is gone (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2017.06.009",children:"Simanshu et al.,\n2017"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:["While RAS is on, it draws in a kinase called RAF. RAF adds a phosphate to a second\nkinase, MEK, and MEK does the same to a third, ERK. ERK adds phosphates to many\nproteins, which together control whether the cell grows, divides, survives, moves or\nmatures (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/s41580-020-0255-7",children:"Lavoie et al., 2020"}),"). Among the\ngenes that growth signals switch on is the one for cyclin D1, which comes back in the RB\nbrake below (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nrd4504",children:"Asghar et al., 2015"}),")."]}),"\n",(0,h.jsxs)(n.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-2-6",children:[(0,h.jsx)(n.img,{alt:"A vertical diagram of a cell. At the top, outside the cell, a growth factor sits in the cup of a receptor that crosses the cell membrane. Arrows lead down from the receptor to RAS, then RAF, MEK and ERK, drawn as boxes, and from ERK into the nucleus, where genes for growth and division switch on. A box for NF1 beside RAS has a blunt line pointing at RAS, labeled turns RAS off. Warning markers connect four points to changes found in cancer. The receptor: EGFR or ERBB2, mutated or amplified. RAS: KRAS G12, G13 or Q61, hard to switch off. NF1: NF1 lost, RAS is slow to switch off. RAF: BRAF V600E, on even without RAS.",src:o().A+"",width:"392",height:"429"}),(0,h.jsx)(n.img,{className:"lg-figure__dark",src:s().A,alt:"A vertical diagram of a cell. At the top, outside the cell, a growth factor sits in the cup of a receptor that crosses the cell membrane. Arrows lead down from the receptor to RAS, then RAF, MEK and ERK, drawn as boxes, and from ERK into the nucleus, where genes for growth and division switch on. A box for NF1 beside RAS has a blunt line pointing at RAS, labeled turns RAS off. Warning markers connect four points to changes found in cancer. The receptor: EGFR or ERBB2, mutated or amplified. RAS: KRAS G12, G13 or Q61, hard to switch off. NF1: NF1 lost, RAS is slow to switch off. RAF: BRAF V600E, on even without RAS.",width:"392",height:"429",loading:"lazy",decoding:"async"}),(0,h.jsxs)(n.figcaption,{children:[(0,h.jsx)(n.span,{className:"lg-figure__number",children:"Figure 2.6"})," The RAS\u2013MAPK relay. A growth factor switches on its receptor, which switches on RAS, and each protein below switches on the next until the signal reaches the nucleus. NF1 helps switch RAS off. The changes marked on the right, found in tumors, make the relay signal more strongly, for longer or without a growth factor. Based on Simanshu et al. (2017) and Davies et al. (2002)."]})]}),"\n",(0,h.jsx)(n.h2,{id:"locking-the-relay-on",children:"Locking the Relay On"}),"\n",(0,h.jsxs)(n.p,{children:["A change in any of several proteins in the relay can keep the signal going after it\nshould have faded (Figure 2.6). Mutations in RAS genes drive about a third of all human\ncancers (",(0,h.jsx)(n.a,{href:"https://www.cancer.gov/research/key-initiatives/ras/about",children:"National Cancer\nInstitute"}),"). The changes at\namino acids 12, 13 and 61 of KRAS that stand out in ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#figure-2-4",children:"Figure\n2.4"})," make RAS resistant to GAPs. Once\nit picks up GTP, it switches itself off only slowly, so it spends far more of its time\nswitched on."]}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.em,{children:"BRAF"}),", one of the genes for RAF, sits one step further down. When researchers screened\ncancers for ",(0,h.jsx)(n.em,{children:"BRAF"})," mutations in 2002, they found them in 66% of the melanomas they\ntested, and a single change, now called V600E, made up 80% of them. The changed protein\nwas a more active kinase, and cancer cells that carried it kept growing without needing\nRAS (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature00766",children:"Davies et al., 2002"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:["The relay can also jam when an off switch is lost. ",(0,h.jsx)(n.em,{children:"NF1"})," makes neurofibromin, a GAP for\nRAS. In tumors that lose it, RAS stays on for longer, with an effect much like a\nmutation in RAS itself. ",(0,h.jsx)(n.em,{children:"NF1"})," is a tumor suppressor that works inside a relay of\noncogenes."]}),"\n",(0,h.jsxs)(n.p,{children:["Because so many genes feed into the same relay, the pathway often tells you more than\nany one gene. In a study of 230 lung adenocarcinomas, 33% of tumors had a ",(0,h.jsx)(n.em,{children:"KRAS"}),"\nmutation and 14% had an ",(0,h.jsx)(n.em,{children:"EGFR"})," mutation, but the two were not found in the same tumor.\nChanges in ",(0,h.jsx)(n.em,{children:"NF1"}),", ",(0,h.jsx)(n.em,{children:"ERBB2"})," and a few other genes in the relay were more common in the\ntumors that had neither. Altogether, 76% of the tumors had the relay switched on in some\nway (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature13385",children:"Cancer Genome Atlas Research Network, 2014"}),").\nA tumor without a ",(0,h.jsx)(n.em,{children:"KRAS"})," mutation may well have the same relay switched on through a\ndifferent gene."]}),"\n",(0,h.jsx)(n.h2,{id:"the-rb-brake",children:"The RB Brake"}),"\n",(0,h.jsxs)(n.p,{children:["The decision to divide is made in the nucleus, where RB, the protein made by the\nretinoblastoma gene ",(0,h.jsx)(n.em,{children:"RB1"})," from ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#two-hits",children:"Two\nHits"}),", guards it. RB holds on to\nproteins called E2F, which switch on the genes a cell needs to copy its DNA and divide\n(",(0,h.jsx)(n.a,{href:"https://doi.org/10.1101/gad.282145.116",children:"Dyson, 2016"}),"). Growth signals raise the level\nof cyclin D, which partners with the kinases CDK4 and CDK6. Together they add phosphates\nto RB, RB lets go of E2F and the cell commits to dividing. A protein called p16, made by\nthe gene ",(0,h.jsx)(n.em,{children:"CDKN2A"}),", blocks CDK4 and CDK6 and keeps the brake on (Figure 2.7)."]}),"\n",(0,h.jsxs)(n.figure,{className:"lg-figure lg-figure--tall lg-figure--themed",id:"figure-2-7",children:[(0,h.jsx)(n.img,{alt:"Two diagrams, one above the other. The RB brake: p16 blocks a box for cyclin D plus CDK4/6, which adds phosphates to RB. RB is drawn holding E2F; an arrow labeled RB lets go leads to E2F on its own, which switches on the genes for dividing. Warning markers show ways tumors break this brake: CDKN2A deleted, next to p16; cyclin D1 too much made, and CDK4 or CDK6 extra copies, under the kinase box; RB1 lost, under RB. The p53 brake: oncogene signals switch on ARF, which blocks MDM2. DNA damage also blocks MDM2. MDM2 blocks p53, and p53 leads to dividing stops or the cell dies. Warning markers show CDKN2A deleted under ARF, MDM2 amplified under MDM2 and TP53 mutated under p53. A key marks proteins that push toward division and proteins that hold division back.",src:r().A+"",width:"392",height:"514"}),(0,h.jsx)(n.img,{className:"lg-figure__dark",src:a().A,alt:"Two diagrams, one above the other. The RB brake: p16 blocks a box for cyclin D plus CDK4/6, which adds phosphates to RB. RB is drawn holding E2F; an arrow labeled RB lets go leads to E2F on its own, which switches on the genes for dividing. Warning markers show ways tumors break this brake: CDKN2A deleted, next to p16; cyclin D1 too much made, and CDK4 or CDK6 extra copies, under the kinase box; RB1 lost, under RB. The p53 brake: oncogene signals switch on ARF, which blocks MDM2. DNA damage also blocks MDM2. MDM2 blocks p53, and p53 leads to dividing stops or the cell dies. Warning markers show CDKN2A deleted under ARF, MDM2 amplified under MDM2 and TP53 mutated under p53. A key marks proteins that push toward division and proteins that hold division back.",width:"392",height:"514",loading:"lazy",decoding:"async"}),(0,h.jsxs)(n.figcaption,{children:[(0,h.jsx)(n.span,{className:"lg-figure__number",children:"Figure 2.7"})," The RB and p53 brakes. In the top half, cyclin D and CDK4/6 add phosphates to RB, which then lets go of E2F, and p16 keeps the brake on by blocking the kinases. In the bottom half, MDM2 keeps p53 in check until oncogene signals, through ARF, or DNA damage block MDM2 and free p53. The marked changes are ways tumors break each brake. CDKN2A appears in both because it makes both p16 and ARF. Based on Asghar et al. (2015) and Kastenhuber and Lowe (2017)."]})]}),"\n",(0,h.jsxs)(n.p,{children:["The brake also responds to the relay. When a relay is jammed on, the cell can make more\np16, which holds RB in place and halts division in a lasting state called ",(0,h.jsx)(n.strong,{children:"senescence"}),"\n(",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/s0092-8674(00)81902-9",children:"Serrano et al., 1997"}),"). To keep\ngrowing, a tumor has to get past this, for example by losing p16."]}),"\n",(0,h.jsxs)(n.p,{children:["A tumor can break the brake at any step. It can lose ",(0,h.jsx)(n.em,{children:"RB1"}),", make too much cyclin D1,\ncarry extra copies of ",(0,h.jsx)(n.em,{children:"CDK4"})," or ",(0,h.jsx)(n.em,{children:"CDK6"})," or delete ",(0,h.jsx)(n.em,{children:"CDKN2A"}),". These changes tend not to\nappear together, and different kinds of tumor favor different ones. RB loss is a\nhallmark of small cell lung cancer (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature14664",children:"George et al.,\n2015"}),"), too much cyclin D1 is common in breast\ncancer (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1007/s12609-012-0083-7",children:"Tobin and Bergh, 2012"}),") and losing\np16 is particularly common in glioblastoma (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2013.09.034",children:"Brennan et al.,\n2013"}),"). Some viruses that cause cancer make\nproteins that switch RB off."]}),"\n",(0,h.jsx)(n.h2,{id:"the-p53-brake",children:"The p53 Brake"}),"\n",(0,h.jsxs)(n.p,{children:["The protein p53, made by ",(0,h.jsx)(n.em,{children:"TP53"}),", responds to trouble rather than to growth signals. Most\nof the time a protein called MDM2 keeps the level of p53 low by marking it for\ndestruction. Damaged DNA, or the stress caused by an oncogene, frees p53 from MDM2. DNA\ndamage adds a phosphate to p53 that blocks MDM2 (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/s0092-8674(00)80416-x",children:"Shieh et al.,\n1997"}),"), and signals from an oncogene\nswitch on a protein called ARF (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1101/gad.12.15.2424",children:"Zindy et al.,\n1998"}),"), which blocks MDM2 directly (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/s0092-8674(00)81400-2",children:"Pomerantz\net al., 1998"}),"). Once free, p53 switches\non genes that stop the cell from dividing, such as the gene for p21, which blocks the\nkinases that drive the cell cycle. If the damage is too great, p53 can make the cell die\ninstead (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/j.cell.2017.08.028",children:"Kastenhuber and Lowe, 2017"}),"), as\nthe lower half of Figure 2.7 shows. This is the checkpoint described in ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#genes-that-guard-the-genome",children:"Genes That\nGuard the Genome"}),"."]}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.em,{children:"TP53"})," is the most frequently mutated gene in human cancer (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/nature12634",children:"Kandoth et al.,\n2013"}),"), and ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/oncogenes-and-tumor-suppressors#figure-2-5",children:"Figure\n2.5"})," shows where its mutations fall. A\ntumor can also switch off p53 without touching ",(0,h.jsx)(n.em,{children:"TP53"}),". In a 1992 study, ",(0,h.jsx)(n.em,{children:"MDM2"})," was\namplified in more than a third of 47 sarcomas, which suggested that the extra MDM2 helps\nthese tumors escape p53's control (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1038/358080a0",children:"Oliner et al.,\n1992"}),")."]}),"\n",(0,h.jsxs)(n.p,{children:[(0,h.jsx)(n.em,{children:"CDKN2A"})," connects the two brakes. The same stretch of DNA is read in two different\n",(0,h.jsx)(n.a,{href:"/docs/biological-foundations/translation#reading-frames",children:"reading frames"})," to make\ntwo unrelated proteins, p16 for the RB brake and ARF for the p53 brake (",(0,h.jsx)(n.a,{href:"https://doi.org/10.1016/0092-8674%2895%2990214-7",children:"Quelle et al.,\n1995"}),"). Deleting the gene removes both\nat once. ",(0,h.jsx)(n.a,{href:"/docs/genomic-variation/copy-number-variation#copy-number-in-cancer",children:"Copy Number\nVariation"}),"\ndescribes how tumors lose both copies of ",(0,h.jsx)(n.em,{children:"CDKN2A"})," in many kinds of cancer."]}),"\n",(0,h.jsx)(n.h2,{id:"up-next",children:"Up Next"}),"\n",(0,h.jsxs)(n.p,{children:["A tumor rarely gets all of these changes at once. ",(0,h.jsx)(n.a,{href:"/docs/cancer-biology/how-tumors-evolve",children:"How Tumors\nEvolve"})," follows how they build up over time, and why tumors\noften find a way around the drugs aimed at them."]})]})}function u(e={}){const{wrapper:n}={...(0,c.R)(),...e.components};return n?(0,h.jsx)(n,{...e,children:(0,h.jsx)(m,{...e})}):m(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>i});var s=t(6540);const a={},o=s.createContext(a);function r(e){const n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);